SELECT * FROM ( SELECT ROWNUM rnum, b.* FROM ( SELECT r.REVIEW_ID AS reviewId, r.PRODUCT_ID AS productId, r.MEMBER_ID AS memberId, r.PRODUCT_OPTION_ID AS productOptionId, r.IS_HIDE_IMAGE AS isHideImage, p.PRODUCT_NAME AS productName, NVL(m.NAME, '탈퇴한 사용자') AS writerName, r.RATING AS rating, r.CONTENT AS content, TO_CHAR(r.REG_DATE, 'YYYY-MM-DD') AS regDate, TO_CHAR(r.EDIT_DATE, 'YYYY-MM-DD') AS editDate, r.ADMIN_REPLY AS adminReply, r.IS_PURCHASED AS isPurchased, img.IMG_ID AS "reviewImage.imgId", img.REVIEW_ID AS "reviewImage.reviewId", img.IMAGE_URL AS "reviewImage.imageUrl", opt.OPTION_NAME AS optionName, (SELECT COUNT(*) FROM REVIEW_LIKE rl WHERE rl.REVIEW_ID = r.REVIEW_ID) AS helpCount FROM REVIEW r JOIN PRODUCT p ON r.PRODUCT_ID = p.PRODUCT_ID LEFT JOIN MEMBER m ON r.MEMBER_ID = m.MEMBER_ID LEFT JOIN ( SELECT REVIEW_ID, IMG_ID, IMAGE_URL FROM ( SELECT REVIEW_ID, IMG_ID, IMAGE_URL, ROW_NUMBER() OVER (PARTITION BY REVIEW_ID ORDER BY IMG_ID ASC) as rn FROM REVIEW_IMAGE ) WHERE rn = 1 ) img ON r.REVIEW_ID = img.REVIEW_ID LEFT JOIN ( SELECT PRODUCT_OPTION_ID, LISTAGG(OPTION_NAME, ' / ') WITHIN GROUP (ORDER BY OPTION_NAME) AS OPTION_NAME FROM ( SELECT DISTINCT pov.PRODUCT_OPTION_ID, ov.OPTION_NAME FROM PRODUCT_OPTION_VALUE pov JOIN OPTION_VALUE ov ON pov.OPTION_VALUE_ID = ov.OPTION_VALUE_ID ) GROUP BY PRODUCT_OPTION_ID ) opt ON r.PRODUCT_OPTION_ID = opt.PRODUCT_OPTION_ID WHERE r.MEMBER_ID = #{member_id} ORDER BY
HELP_COUNT DESC, r.RATING DESC, r.REG_DATE DESC
r.REG_DATE DESC, r.REVIEW_ID DESC
) b WHERE ROWNUM <= #{endRow} ) WHERE rnum >= #{startRow}

SELECT COUNT(*) 
FROM ORDERS o
JOIN ORDERS_DETAIL od ON o.ORDER_ID = od.ORDER_ID
JOIN PRODUCT_OPTION po ON od.PRODUCT_OPTION_ID = po.PRODUCT_OPTION_ID
WHERE o.MEMBER_ID = #{memberId} 
  AND po.PRODUCT_ID = #{productId}
